WITH adjust_fn AS (SELECT p.oid,p.proacl,p.proowner,pg_get_functiondef(p.oid) definition FROM pg_proc p WHERE p.oid=to_regprocedure('public.adjust_shipment_items_v1(uuid,jsonb,text)')),cancel_fn AS (SELECT p.oid,p.proacl,p.proowner,pg_get_functiondef(p.oid) definition FROM pg_proc p WHERE p.oid=to_regprocedure('public.cancel_mistaken_shipments_v1(uuid[],text)')) SELECT audit_issue,detail FROM (SELECT 'adjust_function_missing'::text audit_issue,'Thieu RPC chinh sua phieu giao hang'::text detail WHERE NOT EXISTS(SELECT 1 FROM adjust_fn) UNION ALL SELECT 'adjust_admin_guard_missing','RPC chinh sua chua tu kiem tra quyen Admin' WHERE EXISTS(SELECT 1 FROM adjust_fn WHERE definition NOT ILIKE '%public.is_admin()%') UNION ALL SELECT 'cancel_function_missing','Thieu RPC huy phieu tao nham' WHERE NOT EXISTS(SELECT 1 FROM cancel_fn) UNION ALL SELECT 'cancel_admin_guard_missing','RPC huy phieu chua tu kiem tra quyen Admin' WHERE EXISTS(SELECT 1 FROM cancel_fn WHERE definition NOT ILIKE '%public.is_admin()%') UNION ALL SELECT 'adjust_public_can_execute','PUBLIC van co quyen goi RPC chinh sua' WHERE EXISTS(SELECT 1 FROM adjust_fn CROSS JOIN LATERAL aclexplode(COALESCE(adjust_fn.proacl,acldefault('f',adjust_fn.proowner))) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') UNION ALL SELECT 'adjust_anon_can_execute','anon van co quyen goi RPC chinh sua' WHERE to_regprocedure('public.adjust_shipment_items_v1(uuid,jsonb,text)') IS NOT NULL AND has_function_privilege('anon','public.adjust_shipment_items_v1(uuid,jsonb,text)','EXECUTE') UNION ALL SELECT 'cancel_anon_can_execute','anon van co quyen goi RPC huy phieu' WHERE to_regprocedure('public.cancel_mistaken_shipments_v1(uuid[],text)') IS NOT NULL AND has_function_privilege('anon','public.cancel_mistaken_shipments_v1(uuid[],text)','EXECUTE')) problems ORDER BY audit_issue;
